    #[test]
    fn super_class_chain_terminates_on_every_class_def() {
        // Property: every chain in the fixture must terminate. The
        // depth-cap defense means even a maliciously cyclic chain would
        // halt at MAX_SUPER_CHAIN_DEPTH; clean Java fixtures terminate
        // before that limit (Object's superclass_idx is None).
        let data = include_bytes!("../../tests/fixtures/classes_named.dex");
        let dex = DexFile::parse(data, None).expect("parse");
        assert!(
            !dex.class_defs.is_empty(),
            "fixture must contain at least one class_def"
        );
        for cd in &dex.class_defs {
            let chain: Vec<TypeIdx> = dex.super_class_chain(cd.class_idx).collect();
            assert!(
                chain.len() < MAX_SUPER_CHAIN_DEPTH,
                "chain for {} hit the depth cap — likely a cycle",
                dex.get_type_descriptor(cd.class_idx).unwrap_or("?")
            );
            // Iterator never yields the start type itself.
            assert!(
                !chain.contains(&cd.class_idx),
                "chain for {} contains start type",
                dex.get_type_descriptor(cd.class_idx).unwrap_or("?")
            );
        }
    }

