    // ── parse_errors poison-pill: detectors return Indeterminate ─────────
    //
    // These tests verify the C-1 fix: a `ParseFailure` recorded for a
    // subsection-kind reachable from a detector path MUST cause the
    // detector to return `Indeterminate`, never `No`. The contract is
    // the structural-fix shape — even if a benign fixture is paired
    // with a planted `parse_errors` entry, every detector must surface
    // the poison signal rather than collapse to false.

    #[test]
    fn class_has_kotlin_metadata_indeterminate_on_annotation_item_parse_failure() {
        let data = include_bytes!("../../tests/fixtures/classes_named.dex");
        let mut dex = DexFile::parse(data, None).expect("parse");
        dex.parse_errors.push(ParseFailure {
            kind: ParseFailureKind::AnnotationItem,
            offset: 0x1000,
        });
        for cd in &dex.class_defs {
            assert!(
                dex.class_has_kotlin_metadata(cd.class_idx).is_indeterminate(),
                "class {} returned non-Indeterminate despite planted parse_errors",
                dex.get_type_descriptor(cd.class_idx).unwrap_or("?")
            );
        }
    }

    #[test]
    fn is_kotlin_data_class_never_silently_yes_on_class_data_parse_failure() {
        // The Java fixture has no @kotlin.Metadata, so the metadata gate
        // returns No and short-circuits before class_data is read; the
        // class_data taint is therefore not reachable from the detector's
        // effective query on this fixture and the verdict is No (correct).
        // Contract under test: the detector NEVER silently returns Yes
        // when class_data is poisoned. The fixture-without-metadata case
        // is the strictest test we can write absent a Kotlin fixture.
        let data = include_bytes!("../../tests/fixtures/classes_named.dex");
        let mut dex = DexFile::parse(data, None).expect("parse");
        dex.parse_errors.push(ParseFailure {
            kind: ParseFailureKind::ClassData,
            offset: 0x2000,
        });
        for cd in &dex.class_defs {
            let verdict = dex.is_kotlin_data_class(cd.class_idx);
            assert!(
                !verdict.is_yes(),
                "class {} returned Yes despite planted class_data parse_errors",
                dex.get_type_descriptor(cd.class_idx).unwrap_or("?")
            );
        }
    }

