    #[test]
    fn subsection_clean_recognizes_each_detector_kind() {
        // Foundation invariant for the helper itself: every kind we
        // poison must be reflected in subsection_clean. Guards against
        // future ParseFailureKind variants being silently omitted from
        // detectors' gate sets.
        let data = include_bytes!("../../tests/fixtures/classes_named.dex");
        for kind in &[
            ParseFailureKind::AnnotationDirectory,
            ParseFailureKind::AnnotationSet,
            ParseFailureKind::AnnotationSetRefList,
            ParseFailureKind::AnnotationItem,
            ParseFailureKind::ClassData,
        ] {
            let mut dex = DexFile::parse(data, None).expect("parse");
            assert!(dex.subsection_clean(&[*kind]));
            dex.parse_errors.push(ParseFailure {
                kind: *kind,
                offset: 0x100,
            });
            assert!(
                !dex.subsection_clean(&[*kind]),
                "subsection_clean failed to detect planted {:?}",
                kind
            );
        }
    }

    /// Build a stub `DexHeader` whose `string_ids_off` / `string_ids_size`
    /// point at a hand-built two-entry string pool packed into `data`.
    /// Other fields are zeroed; `parse_strings` only reads
    /// `string_ids_off` + `string_ids_size`, so the stub suffices.
    fn header_for_two_string_pool(data: &[u8]) -> crate::header::DexHeader {
        let mut magic = [0u8; 8];
        magic[..4].copy_from_slice(b"dex\n");
        magic[4..7].copy_from_slice(b"035");
        crate::header::DexHeader {
            magic,
            checksum: 0,
            signature: [0u8; 20],
            file_size: data.len() as u32,
            header_size: 112,
            endian_tag: 0x1234_5678,
            link_size: 0,
            link_off: 0,
            map_off: 0,
            string_ids_size: 2,
            string_ids_off: 0,
            type_ids_size: 0,
            type_ids_off: 0,
            proto_ids_size: 0,
            proto_ids_off: 0,
            field_ids_size: 0,
            field_ids_off: 0,
            method_ids_size: 0,
            method_ids_off: 0,
            class_defs_size: 0,
            class_defs_off: 0,
            data_size: 0,
            data_off: 0,
        }
    }

    /// Construct a near-empty `DexFile` carrying only the strings
    /// under test, so the public `string_has_lossy_decode` accessor
    /// can be exercised. The accessor delegates to
    /// `dex.strings[idx].is_lossy()`.
    fn dex_from_strings(strings: Vec<crate::DexString>) -> DexFile {
        DexFile {
            header: header_for_two_string_pool(&[]),
            string_data_offs: vec![0; strings.len()],
            strings,
            type_descriptors: Vec::new(),
            protos: Vec::new(),
            fields: Vec::new(),
            methods: Vec::new(),
            class_defs: Vec::new(),
            annotations: BTreeMap::new(),
            type_lists: BTreeMap::new(),
            class_datas: BTreeMap::new(),
            raw_class_data_bytes: BTreeMap::new(),
            code_items: BTreeMap::new(),
            annotation_sets: BTreeMap::new(),
            annotation_set_ref_lists: BTreeMap::new(),
            annotation_items: BTreeMap::new(),
            annotation_item_widths: BTreeMap::new(),
            encoded_arrays: BTreeMap::new(),
            encoded_array_widths: BTreeMap::new(),
            method_handles: Vec::new(),
            call_site_ids: Vec::new(),
            map_entries: Vec::new(),
            debug_infos: BTreeMap::new(),
            debug_info_raw_bytes: BTreeMap::new(),
            debug_info_section_layout: Vec::new(),
            annotation_set_section_layout: Vec::new(),
            input_checksums_canonical: true,
            parse_errors: Vec::new(),
            class_def_index: Vec::new(),
        }
    }

    /// Precision gate (acceptance gate 2): a string-pool entry whose raw
    /// MUTF-8 bytes are `0xC0 0x80` (encoded NUL) round-trips correctly
    /// through `decode_mutf8` to "\0". A naive byte-diff implementation
    /// would flag this as lossy because raw≠decoded; the precise gauge
    /// must report `false`.
    #[test]
    fn string_has_lossy_decode_false_on_encoded_nul_roundtrip() {
        // Layout: [string_ids][string_data #1 (encoded NUL)][string_data #2 (single 'A')]
        // string_ids: 2 × u32 LE pointing to string_data offsets.
        let mut data = Vec::new();
        // Reserve 8 bytes for the two-entry string_ids table.
        data.extend_from_slice(&[0u8; 8]);
        // string_data #1 at offset 8: char_count=1 ULEB, raw=[C0 80], terminator.
        let off1: u32 = data.len() as u32;
        data.extend_from_slice(&[0x01, 0xC0, 0x80, 0x00]);
        // string_data #2 at offset 12: char_count=1, raw=[0x41 'A'], terminator.
        let off2: u32 = data.len() as u32;
        data.extend_from_slice(&[0x01, 0x41, 0x00]);
        // Patch string_ids[0..4] = off1, string_ids[4..8] = off2.
        data[0..4].copy_from_slice(&off1.to_le_bytes());
        data[4..8].copy_from_slice(&off2.to_le_bytes());

        let header = header_for_two_string_pool(&data);
        let (strings, _) = DexFile::parse_string_pool(&data, &header).expect("parse_string_pool ok");

        assert_eq!(strings.len(), 2, "two strings parsed");
        assert_eq!(strings[0].as_str_lossy(), "\0", "encoded NUL decodes to NUL char");
        assert_eq!(strings[1].as_str_lossy(), "A", "ASCII control");
        assert!(!strings[0].is_lossy(), "encoded NUL is byte-clean MUTF-8 — must NOT be lossy");
        assert!(!strings[1].is_lossy(), "ASCII 'A' is byte-clean — must NOT be lossy");

        // Exercise the public accessor with a constructed DexFile.
        let dex = dex_from_strings(strings);
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(0)),
            Some(false),
            "accessor must report Some(false) for encoded NUL (precision gate)"
        );
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(1)),
            Some(false),
            "accessor must report Some(false) for ASCII 'A'"
        );
    }

    /// Lossy-detection gate (acceptance gate 3): a string-pool entry with
    /// `ED A0 80 EE 81 9F` (lone high surrogate followed by a non-low-
    /// surrogate 3-byte sequence) is the empirically-dominant failure
    /// shape per closed `droidsaw-audit-mutf8-codec-bypass-fix` corpus
    /// measurement. `decode_mutf8` must return `Err` and the parser
    /// must record `marks[idx] = true`.
    #[test]
    fn string_has_lossy_decode_true_on_lone_high_surrogate() {
        let mut data = Vec::new();
        data.extend_from_slice(&[0u8; 8]);
        // string_data #1: char_count=2 ULEB, raw=[ED A0 80 EE 81 9F], terminator.
        let off1: u32 = data.len() as u32;
        data.extend_from_slice(&[0x02, 0xED, 0xA0, 0x80, 0xEE, 0x81, 0x9F, 0x00]);
        // string_data #2: char_count=1, raw='B', terminator (control case — clean).
        let off2: u32 = data.len() as u32;
        data.extend_from_slice(&[0x01, 0x42, 0x00]);
        data[0..4].copy_from_slice(&off1.to_le_bytes());
        data[4..8].copy_from_slice(&off2.to_le_bytes());

        let header = header_for_two_string_pool(&data);
        let (strings, _) = DexFile::parse_string_pool(&data, &header).expect("parse_string_pool ok");

        assert_eq!(strings.len(), 2);
        assert!(
            strings[0].is_lossy(),
            "lone high surrogate followed by non-low-surrogate must store MalformedMutf8"
        );
        assert!(!strings[1].is_lossy(), "ASCII 'B' is byte-clean — must NOT be lossy");

        let dex = dex_from_strings(strings);
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(0)),
            Some(true),
            "accessor must report Some(true) for lone-high-surrogate (precision gate)"
        );
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(1)),
            Some(false),
            "accessor must report Some(false) for the byte-clean control"
        );
    }

    /// Regression: OOB idx must return `None`, NOT silently `false`
    /// (a bool-return contract conflates "no such string" with "string
    /// exists and decoded cleanly"; the typed-return distinguishes
    /// the two cases at the boundary).
    #[test]
    fn string_has_lossy_decode_returns_none_on_oob() {
        let dex = dex_from_strings(vec![crate::DexString::from_decoded_str("A")]);
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(0)),
            Some(false),
            "idx=0 is in range; clean ASCII → Some(false)"
        );
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(1)),
            None,
            "idx=1 is out of range (only 1 string in pool) → None"
        );
        assert_eq!(
            dex.string_has_lossy_decode(StringIdx(u32::MAX)),
            None,
            "idx=u32::MAX is out of range → None"
        );
    }

