    #[test]
    fn class_def_off_zero_always_accepted() {
        // `off = 0` is the spec sentinel for "absent"; must pass for
        // every field tag, regardless of data_len (even data_len = 0).
        for field in [
            "interfaces_off",
            "annotations_off",
            "class_data_off",
            "static_values_off",
        ] {
            assert_eq!(validate_class_def_off(0, field, 0).unwrap(), 0);
            assert_eq!(validate_class_def_off(0, field, 1024).unwrap(), 0);
        }
    }

    #[test]
    fn class_def_off_in_bounds_accepted() {
        // off ∈ (0, data_len) is accepted for every field.
        for field in [
            "interfaces_off",
            "annotations_off",
            "class_data_off",
            "static_values_off",
        ] {
            assert_eq!(validate_class_def_off(1, field, 1024).unwrap(), 1);
            assert_eq!(validate_class_def_off(1023, field, 1024).unwrap(), 1023);
        }
    }

    #[test]
    fn class_def_off_at_or_past_data_len_rejected() {
        // off >= data_len rejected with field tag + payload preserved.
        let err =
            validate_class_def_off(1024, "interfaces_off", 1024).unwrap_err();
        assert!(
            matches!(
                err,
                DexError::ClassDefOffsetOutOfBounds {
                    field: "interfaces_off",
                    off: 1024,
                    data_len: 1024,
                }
            ),
            "got {err:?}",
        );
    }

    #[test]
    fn class_def_off_u32_max_rejected_each_field() {
        // Regression: each offset field at u32::MAX. Must
        // surface as ClassDefOffsetOutOfBounds with the correct field
        // tag for each call.
        for field in [
            "interfaces_off",
            "annotations_off",
            "class_data_off",
            "static_values_off",
        ] {
            let err = validate_class_def_off(u32::MAX, field, 4096).unwrap_err();
            match err {
                DexError::ClassDefOffsetOutOfBounds {
                    field: got_field,
                    off,
                    data_len,
                } => {
                    assert_eq!(got_field, field);
                    assert_eq!(off, u32::MAX);
                    assert_eq!(data_len, 4096);
                }
                other => panic!("expected ClassDefOffsetOutOfBounds, got {other:?}"),
            }
        }
    }

    #[test]
    fn class_def_off_field_tag_carried_verbatim() {
        // Audit-attribution invariant: the error variant carries the
        // exact field tag the caller passed in. This is the load-
        // bearing improvement over the prior deferred-Err shape —
        // operators see the parse-time origin, not the consumer site.
        let err = validate_class_def_off(99999, "class_data_off", 1024).unwrap_err();
        let DexError::ClassDefOffsetOutOfBounds {
            field, off, data_len,
        } = err else {
            panic!("expected ClassDefOffsetOutOfBounds");
        };
        assert_eq!(field, "class_data_off");
        assert_eq!(off, 99999);
        assert_eq!(data_len, 1024);
    }

    #[test]
    fn rebuild_class_def_index_first_wins_on_duplicate_class_idx() {
        // Regression test for duplicate class_idx handling.
        //
        // Without the guard: `rebuild_class_def_index` silently overwrote the
        // slot on duplicate class_idx, leaving `class_def_for_type` resolving
        // to the LAST row while linear-scan callers saw both —
        // index-vs-iteration disagreement evasion primitive.
        //
        // With the guard: first-wins per Android AOSP `DexFile::FindClassDef`,
        // and the duplicate emits a `ParseFailureKind::DuplicateClassDef`
        // entry into `parse_errors` for diag surfacing.
        let data = include_bytes!("../../tests/fixtures/classes_named.dex");
        let mut dex = DexFile::parse(data, None).expect("parse fixture");

        // Pick any existing class_def and plant a duplicate row carrying
        // the SAME class_idx but a distinguishable access_flags marker
        // so we can verify the slot pinned to the FIRST.
        let first = dex.class_defs.first().cloned().expect("fixture has classes");
        let first_idx = 0u32;
        let mut duplicate = first.clone();
        duplicate.access_flags = first.access_flags ^ 0x0010; // flip a bit so first != duplicate
        let dup_class_defs_idx = u32::try_from(dex.class_defs.len()).expect("≤ u32::MAX");
        dex.class_defs.push(duplicate);

        let prior_parse_errors_len = dex.parse_errors.len();
        dex.rebuild_class_def_index();

        // Index slot for the shared class_idx must point at the FIRST row.
        let slot = dex
            .class_def_index
            .get(first.class_idx.0 as usize)
            .copied()
            .flatten()
            .expect("index slot populated");
        assert_eq!(
            slot, first_idx,
            "first-wins: index must pin to the FIRST class_defs row sharing class_idx"
        );

        // class_def_for_type O(1) lookup must return the FIRST row.
        let via_index = dex
            .class_def_for_type(first.class_idx)
            .expect("class_def_for_type resolves shared class_idx");
        assert_eq!(
            via_index.access_flags, first.access_flags,
            "class_def_for_type must return the FIRST row's access_flags"
        );

        // The duplicate must have generated a ParseFailure record.
        let new_failures: Vec<_> = dex
            .parse_errors
            .iter()
            .skip(prior_parse_errors_len)
            .filter(|p| p.kind == ParseFailureKind::DuplicateClassDef)
            .collect();
        assert_eq!(
            new_failures.len(),
            1,
            "exactly one DuplicateClassDef ParseFailure must surface; got {:?}",
            dex.parse_errors
        );
        assert_eq!(
            new_failures[0].offset, dup_class_defs_idx,
            "ParseFailure.offset must carry the duplicate row's class_defs index"
        );
    }

